    drawLoadDisplay(18.4);

    // -------------------------------------------------------------------------
    // Direct camera controls: orbit, zoom, keyboard, and touch pinch
    // -------------------------------------------------------------------------

    const cameraState = {
      target: new THREE.Vector3(0, 1.75, 0),
      yaw: 0.72,
      pitch: 0.58,
      distance: 16.8
    };

    function updateCamera() {
      const cp = Math.cos(cameraState.pitch);
      camera.position.set(
        cameraState.target.x +
          cameraState.distance * cp * Math.sin(cameraState.yaw),
        cameraState.target.y +
          cameraState.distance * Math.sin(cameraState.pitch),
        cameraState.target.z +
          cameraState.distance * cp * Math.cos(cameraState.yaw)
      );
      camera.lookAt(cameraState.target);
    }

    function setCamera(view) {
      if (view === "detail") {
        cameraState.target.set(0, 1.9, 0);
        cameraState.yaw = 0.38;
        cameraState.pitch = 0.34;
        cameraState.distance = 10.2;
      } else {
        cameraState.target.set(0, 1.75, 0);
        cameraState.yaw = 0.72;
        cameraState.pitch = 0.58;
        cameraState.distance = 16.8;
      }
      updateCamera();
    }

    const pointers = new Map();
    let pinchDistance = 0;

    renderer.domElement.addEventListener("pointerdown", (event) => {
      renderer.domElement.setPointerCapture(event.pointerId);
      pointers.set(event.pointerId, { x: event.clientX, y: event.clientY });

      if (pointers.size === 2) {
        const [a, b] = [...pointers.values()];
        pinchDistance = Math.hypot(a.x - b.x, a.y - b.y);
      }
    });

    renderer.domElement.addEventListener("pointermove", (event) => {
      if (!pointers.has(event.pointerId)) return;

      const previous = pointers.get(event.pointerId);
      const current = { x: event.clientX, y: event.clientY };
      pointers.set(event.pointerId, current);

      if (pointers.size === 1) {
        const dx = current.x - previous.x;
        const dy = current.y - previous.y;

        cameraState.yaw -= dx * 0.006;
        cameraState.pitch = THREE.MathUtils.clamp(
          cameraState.pitch + dy * 0.005,
          0.16,
          1.28
        );
      } else if (pointers.size === 2) {
        const [a, b] = [...pointers.values()];
        const distance = Math.hypot(a.x - b.x, a.y - b.y);

        if (pinchDistance > 0 && distance > 0) {
          cameraState.distance = THREE.MathUtils.clamp(
            cameraState.distance * (pinchDistance / distance),
            6.5,
            29
          );
        }

        pinchDistance = distance;
      }

      updateCamera();
    });

    function releasePointer(event) {
      pointers.delete(event.pointerId);
      if (pointers.size < 2) pinchDistance = 0;
    }

    renderer.domElement.addEventListener("pointerup", releasePointer);
    renderer.domElement.addEventListener("pointercancel", releasePointer);

    renderer.domElement.addEventListener(
      "wheel",
      (event) => {
        event.preventDefault();
        cameraState.distance = THREE.MathUtils.clamp(
          cameraState.distance * Math.exp(event.deltaY * 0.001),
          6.5,
          29
        );
        updateCamera();
      },
      { passive: false }
    );

    renderer.domElement.addEventListener("dblclick", () => {
      setCamera("overview");
    });

    addEventListener("keydown", (event) => {
      if (event.key === "1") setCamera("overview");
      if (event.key === "2") setCamera("detail");
    });

    // -------------------------------------------------------------------------
    // UI
    // -------------------------------------------------------------------------

    const loadSlider = document.getElementById("load-slider");
    const loadState = document.getElementById("load-state");
