    function updateLoadUI() {
      loadWeight = Number(loadSlider.value);
      loadSlider.style.setProperty(
        "--load",
        `${((loadWeight - 12) / (30 - 12)) * 100}%`
      );

      axleLoad.innerHTML = `${(loadWeight / 2).toFixed(1)} <small>t</small>`;
      drawLoadDisplay(loadWeight);

      const labelCanvas = document.createElement("canvas");
      labelCanvas.width = 768;
      labelCanvas.height = 256;
