      labelCtx.strokeStyle = "#ffb13b";
      labelCtx.lineWidth = 12;
      labelCtx.strokeRect(12, 12, 744, 232);
      labelCtx.fillStyle = "#ffb13b";
      labelCtx.font = "800 65px system-ui, sans-serif";
      labelCtx.fillText("CALIBRATION MASS", 48, 105);
      labelCtx.fillStyle = "#eaf3f7";
      labelCtx.font = "700 42px system-ui, sans-serif";
      labelCtx.fillText(`${loadWeight.toFixed(1)} t`, 49, 178);

      const labelTexture = new THREE.CanvasTexture(labelCanvas);
      labelTexture.colorSpace = THREE.SRGBColorSpace;
