      loadState.textContent = paused ? "Hold" : "Calibrated";
    });

    document.getElementById("overview-button").addEventListener("click", () => {
      setCamera("overview");
    });

    document.getElementById("detail-button").addEventListener("click", () => {
      setCamera("detail");
    });

    // -------------------------------------------------------------------------
    // Animation
    // -------------------------------------------------------------------------

    const clock = new THREE.Clock();
    let elapsed = 0;
    let wheelAngle = 0;
    let rollerAngle = 0;
    let frameNumber = 0;

    function animate() {
      requestAnimationFrame(animate);

      const dt = Math.min(clock.getDelta(), 0.05);
      const now = performance.now();

      if (!paused) {
        elapsed += dt;

        // Small reciprocating bogie motion on the roller bed.
        const bogieX = Math.sin(elapsed * 0.42) * 0.32;
        const bogieVelocity = Math.cos(elapsed * 0.42) * 0.32 * 0.42;

        bogie.position.x = bogieX;

        // No-slip rolling, with opposite signs for the two assemblies.
        wheelAngle -= (bogieVelocity / 0.62) * dt;
        rollerAngle -= (bogieVelocity / 0.38) * dt;

        for (const wheel of wheelGroups) {
          wheel.rotation.z = wheelAngle;
        }

        for (const roller of rollerGroups) {
          roller.rotation.z = rollerAngle;
        }
      }

      // Slightly animate the signal lamp pulse.
      if (!paused) {
        redLamp.material.emissiveIntensity =
