        new THREE.Vector3(-8.7, 3.0, 2.35),
        new THREE.Vector3(bogieX + 2.7, 2.75, 1.2),
        new THREE.Vector3(bogieX + 2.2, 1.95, 0.75)
      ];

      cableCurve.points.set(cablePoints);
      cableCurve.autoClose = false;

      if (frameNumber % 2 === 0) {
        const nextGeometry = new THREE.TubeGeometry(
          cableCurve,
          48,
          0.035,
          6,
          false
        );
        cable.geometry.dispose();
        cable.geometry = nextGeometry;
